                s0 += a * Q[j, 0]
                s1 += a * Q[j, 1]
            W[i, 0] = s0; W[i, 1] = s1
        b00 = 0.0; b01 = 0.0; b10 = 0.0; b11 = 0.0
        for i in range(n):
            q0 = Q[i, 0]; q1 = Q[i, 1]
            b00 += q0 * W[i, 0]; b01 += q0 * W[i, 1]
            b10 += q1 * W[i, 0]; b11 += q1 * W[i, 1]
