        if disc >= 0.0:
            sd = np.sqrt(disc)
            l1 = (tr + sd) * 0.5
            l2 = (tr - sd) * 0.5
            if abs(l1) >= abs(l2):
                lam = l1
            else:
                lam = l2
            m1 = abs(b01) + abs(b00 - lam)
            m2 = abs(b10) + abs(b11 - lam)
            if m1 >= m2:
                y0 = b01; y1 = lam - b00
                if y0 == 0.0 and y1 == 0.0:
                    y0 = 1.0; y1 = 0.0
            else:
