            y0 /= nrm; y1 /= nrm
            ok = True
            for i in range(n):
                xi = Q[i,0]*y0 + Q[i,1]*y1
                wi = W[i,0]*y0 + W[i,1]*y1
                ri = wi - lam*xi
                lim = 1e-9 + 1e-6*abs(lam*xi)
                if abs(ri) > lim:
                    ok = False
                    break
            if ok:
                for i in range(n):
                    out[i] = complex(Q[i,0]*y0 + Q[i,1]*y1, 0.0)
                return True, lam, 0.0, out
