            lr = tr * 0.5
            li = sd * 0.5
            m1 = abs(b01) + np.sqrt((lr-b00)*(lr-b00) + li*li)
            m2 = abs(b10) + np.sqrt((lr-b11)*(lr-b11) + li*li)
