                xim = q0*y0i + q1*y1i
                wr = W[i,0]*y0r + W[i,1]*y1r
                wi_ = W[i,0]*y0i + W[i,1]*y1i
                lx_r = lr*xr - li*xim
                lx_i = lr*xim + li*xr
                rr = wr - lx_r
                ri_ = wi_ - lx_i
                rmag = np.sqrt(rr*rr + ri_*ri_)
                bl = np.sqrt(lx_r*lx_r + lx_i*lx_i)
                if rmag > 1e-9 + 1e-6*bl:
