            for i in range(n):
                Q[i,1] = -Q[jmin,0]*Q[i,0]
            Q[jmin,1] += 1.0
            n2 = 0.0
            for i in range(n):
                n2 += Q[i,1]*Q[i,1]
            n2 = np.sqrt(n2)
            for i in range(n):
                Q[i,1] /= n2
        else:
            for i in range(n):
