    return False, 0.0, 0.0, out

def fast(A, max_iter=300):
    n = A.shape[0]
    if n == 1:
        return complex(A[0,0]), np.array([1.0+0j])
    if n == 2:
        a,b = A[0,0], A[0,1]
        c,d = A[1,0], A[1,1]
        tr = a+d; det = a*d-b*c; disc = tr*tr-4*det
        if disc >= 0:
            import math
            sd = math.sqrt(disc)
            l1=(tr+sd)/2; l2=(tr-sd)/2
            lam = l1 if abs(l1)>=abs(l2) else l2
            m1=abs(b)+abs(a-lam); m2=abs(c)+abs(d-lam)
            if m1>=m2:
                v=np.array([b, lam-a],dtype=np.complex128)
                if v[0]==0 and v[1]==0: v=np.array([1,0],dtype=np.complex128)
            else:
                v=np.array([lam-d, c],dtype=np.complex128)
                if v[0]==0 and v[1]==0: v=np.array([1,0],dtype=np.complex128)
            # return real if imag zero
            if np.iscomplexobj(v) and np.all(v.imag==0):
                return float(lam), v.real.copy()
            return complex(lam), v
        else:
            import math
            sd=math.sqrt(-disc); lr=tr/2; li=sd/2
            lam=complex(lr,li)
            v=np.array([complex(b,0), complex(lr-a, li)],dtype=np.complex128)
            if v[0]==0 and v[1]==0:
                v=np.array([complex(lr-d,li), complex(c,0)],dtype=np.complex128)
            return lam, v
    ok, lr, li, vec = _kernel(np.ascontiguousarray(A, dtype=np.float64), max_iter)
    if ok:
        if li == 0.0:
            return float(lr), vec.real.copy()
        return complex(lr, li), vec
    # fallback
    w, V = np.linalg.eig(A)
    idx = np.argmax(np.abs(w))
    return w[idx], V[:, idx]

# correctness test
rng = np.random.default_rng(0)
fails = 0; nb_fail=0
for t in range(2000):
    n = int(rng.integers(2, 11))
    A = rng.normal(size=(n,n)).astype(np.float64)
    try:
        lam, vec = fast(A)
        assert not np.allclose(vec, 0) and not np.isnan(lam.real if np.iscomplex(lam) else lam)
        assert np.allclose(A@vec, lam*vec), f"resid {np.linalg.norm(A@vec-lam*vec)}"
    except AssertionError as e:
        fails += 1
        if fails < 5: print("FAIL", n, e)
print("fails:", fails, "/2000")
